uniform float speed : 0.0 .. 3.0 = 1.0;
uniform float count : 1.0 .. 6.0 = 3.0;
uniform float size  : 0.05 .. 0.5 = 0.25;
uniform vec3 col1 : color = 1.0, 0.2, 0.1;
uniform vec3 col2 : color = 0.1, 0.3, 1.0;

state fixed ph;
state fixed ang[6];
state fixed rad[6];
state fixed hgt[6];
state bool inited;

void update() {
  ph = fract(ph + fixed(dt * speed * fixed(0.15)));
  if (!inited) {
    for (int i = 0; i < 6; i = i + 1) {
      ang[i] = fixed(hash(float(i) * fixed(7.0)));
      rad[i] = fixed(0.08) * fixed(0.6) + fixed(hash(float(i) * fixed(11.0))) * fixed(0.08) * fixed(0.3);
      hgt[i] = fixed(hash(float(i) * fixed(13.0))) * fixed(0.30);
    }
    inited = true;
  }
}

vec3 shade(Led led) {
  fixed p = fixed(led.pos.y) / fixed(0.30);
  fixed s = fixed(led.s);
  vec3 c = vec3(0.0, 0.0, 0.0);
  fixed n = fixed(count);
  for (int i = 0; i < 6; i = i + 1) {
    fixed dx = fixed(led.pos.x) - sin(ang[i] + ph * fixed(2.0)) * rad[i];
    fixed dy = fixed(led.pos.z) - cos(ang[i] + ph * fixed(2.0)) * rad[i];
    fixed d2 = dx * dx + dy * dy;
    fixed rr = rad[i] * rad[i];
    fixed g = clamp(fixed(1.0) - d2 / rr, fixed(0.0), fixed(1.0));
    fixed lift = fixed(0.5) + fixed(0.5) * sin(p * fixed(count * 2.0) + ph + fixed(i));
    fixed yy = abs(p - hgt[i]) * fixed(2.0) * fixed(size);
    fixed gv = clamp(fixed(1.0) - yy, fixed(0.0), fixed(1.0));
    fixed m = g * gv * lift;
    float t = float(m);
    c = c + mix(col1, col2, t) * t;
  }
  return c;
}
